import json

# Fix entity values - need correct lengths
entity_vals_by_phase = [
    [[4, 4, 4, 4, 4]],  # phase 0
    [[4, 4, 0, 0, 0]],  # phase 1
    [[5, 5, 0, 0, 0]],  # phase 2
    [[5, 5, 5, 9, 9]],  # phase 3
    [[5, 5, 5, 9, 9]],  # phase 4
    [[4, 5, 5, 9, 9]],  # phase 5
    [[4, 5, 5, 9, 9]],  # phase 6
    [[4, 4, 4, 4, 4]],  # phase 7
]

def get_entity_values(phase):
    return [v for e in entity_vals_by_phase[phase] for v in e]

full_output = []
for r in range(22):
    phase = r // 3
    if phase >= 7: phase = 7

    entity_vals = get_entity_values(phase)  # entity_vals is [v0, v1, v2, v3, v4]

    row = []
    for c in range(27):
        if r in [0, 21]:
            row.append(4)
        elif r in [3, 6, 9, 12, 15, 18]:
            if c in [2, 8, 14, 20, 26]:
                idx = (c - 2) // 6
                row.append(entity_vals[idx])
            else:
                row.append(4)
        else:
            # Content rows
            if c <= 1:
                row.append(entity_vals[0])
            elif c < 8:
                row.append(entity_vals[1])
            elif c < 14:
                row.append(entity_vals[2])
            elif c < 20:
                row.append(entity_vals[3])
            else:
                row.append(entity_vals[4])

    full_output.append(row)

print("Rows 0-2 (phase 0):")
for row in full_output[0:3]:
    print(row)
print("\nRows 3-5 (phase 1):")
for row in full_output[3:6]:
    print(row)
print("\nRows 6-8 (phase 2):")
for row in full_output[6:9]:
    print(row)
print("\nRows 9-11 (phase 3):")
for row in full_output[9:12]:
    print(row)

action = {"action": "submit", "grid": full_output}
print("\nTrying:", json.dumps(action))

